content.css:
.marquee-container {
  width: 100%;
  height: 100%;
  min-height: 65px;
  overflow: hidden;
  display: flex;
  flex-direction: column;
  justify-content: center;
  background: #111827;
  border-radius: 8px;
  padding: 12px 20px;
  box-sizing: border-box;
}
.marquee-header {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-bottom: 12px;
}
.marquee-title {
  font-family: Arial, sans-serif;
  font-size: 18px;
  font-weight: 700;
  line-height: 1.3;
}
.marquee-subtitle {
  font-family: Arial, sans-serif;
  font-size: 12px;
  line-height: 1.4;
}
.marquee-viewport {
  width: 100%;
  overflow: hidden;
}
.marquee-track {
  display: flex;
  align-items: center;
  width: max-content;
  flex-shrink: 0;
  will-change: transform;
}
.marquee-group {
  display: flex;
  align-items: center;
  flex-shrink: 0;
  gap: 25px;
  padding-right: 25px;
}
.product-item {
  display: flex;
  align-items: center;
  gap: 12px;
  white-space: nowrap;
  font-family: Arial, sans-serif;
}
.product-name {
  color: var(--product-name-color, #ffffff);
  font-size: var(--product-font-size, 15px);
  font-weight: 600;
  display: var(--show-product-name, inline);
}
.product-price {
  color: var(--price-color, #4ade80);
  font-size: var(--price-font-size, 15px);
  font-weight: 700;
  display: var(--show-price, inline);
}
.product-separator {
  color: var(--separator-color, #64748b);
  font-size: 18px;
}
.marquee-message {
  color: #ffffff;
  font-family: Arial, sans-serif;
  font-size: 14px;
}
